from pathlib import Path
import html
R=Path(__file__).resolve().parents[1]
variants=[('editorial','01','Редакционный','Текст, фотография, характер.'),('product','02','Продуктовый','Сначала покажем, как это работает.'),('atmosphere','03','Атмосферный','Тёмная сцена. Спокойное движение.')]
nav=''.join(f'<a href="/bots-lab/{slug}/" data-variant="{slug}"><span>{n}</span> {name}</a>' for slug,n,name,_ in variants)
def header(n):return f'''<a class="skip" href="#main">К содержанию</a><div class="lab-bar"><a href="/bots-lab/">Дизайн-лаборатория</a><span>Три взгляда на одну задачу / {n}</span><a href="/">Основной сайт ↗</a></div><header class="header wrap"><a class="identity" href="/"><span class="identity-mark" aria-hidden="true">м.</span><span>Илья Маник<small>Разработка ботов для бизнеса</small></span></a><nav aria-label="Навигация страницы"><a href="#tasks">Задачи</a><a href="#demo">Пример</a><a class="nav-contact" href="/contacts/">Обсудить бота <span aria-hidden="true">↗</span></a></nav></header>'''
lead='Разрабатываю ботов, которые принимают заявки, записывают клиентов и передают нужную информацию вашей команде.'
def demo():return '''<section class="demo-section wrap" id="demo"><div class="demo-copy"><p class="kicker">02 / Попробуйте сценарий</p><h2>Один диалог.<br>Меньше ручной работы.</h2><p>Посмотрите, как обычное сообщение превращается в понятную задачу для бизнеса.</p><div class="scenario-tabs" role="tablist" aria-label="Сценарий бота"><button role="tab" id="tab-booking" aria-controls="demo-panel" aria-selected="true" data-scenario="booking">Запись</button><button role="tab" id="tab-lead" aria-controls="demo-panel" aria-selected="false" tabindex="-1" data-scenario="lead">Заявка</button><button role="tab" id="tab-support" aria-controls="demo-panel" aria-selected="false" tabindex="-1" data-scenario="support">Вопрос</button></div><p class="demo-disclaimer">Демонстрация. Реальная запись не создаётся, данные никуда не отправляются.</p></div><div class="demo-window" id="demo-panel" role="tabpanel" aria-labelledby="tab-booking"><div class="window-top"><span class="bot-avatar" aria-hidden="true">м.</span><div><strong>Помощник бизнеса</strong><small>Пример сценария</small></div><span class="demo-label">DEMO</span></div><div class="chat-log" aria-live="polite" aria-atomic="true"><div class="chat-message client"><span class="sender">Клиент</span><p>Хочу записаться на консультацию.</p></div><div class="chat-message"><span class="sender">Бот</span><p>Помогу выбрать услугу и удобное время. Сценарии можно переключать при включённом JavaScript.</p></div></div><div class="demo-bottom"><span class="demo-progress" role="status"></span><button class="demo-next" hidden>Дальше <span aria-hidden="true">→</span></button></div></div></section>'''
tasks='''<section class="task-section wrap" id="tasks"><div class="section-intro"><p class="kicker">01 / Где поможет бот</p><h2>Повторяется каждый день?<br>Пора передать боту.</h2><p>Начнём с конкретной задачи, которая отнимает время. Не обязательно автоматизировать весь бизнес сразу.</p></div><div class="task-list"><article><span class="task-number">01</span><h3>Не потерять обращение</h3><p>Бот уточняет запрос, собирает контакты и передаёт заявку менеджеру. Клиенту не приходится повторять всё заново.</p><span class="task-result">Сообщение → готовая заявка</span></article><article><span class="task-number">02</span><h3>Записать без переписки</h3><p>Помогает выбрать услугу и время. При подключении к расписанию проверяет доступность и отправляет напоминания.</p><span class="task-result">Услуга → время → запись</span></article><article><span class="task-number">03</span><h3>Ответить на знакомый вопрос</h3><p>Подсказывает условия, сроки и порядок действий. Если вопрос нестандартный — подключает человека.</p><span class="task-result">Вопрос → ответ или менеджер</span></article></div></section>'''
process='''<section class="process-section wrap" id="process"><p class="kicker">03 / Работа над проектом</p><div class="process-heading"><h2>Сначала разберём процесс.<br>Потом напишем код.</h2><p>Сценарий важнее количества функций. Бот должен быть понятен клиенту и полезен вашей команде.</p></div><ol class="process-list"><li><span>01</span><div><h3>Разбираем задачу</h3><p>Кто пишет, что спрашивает, где теряется время и куда должна попасть информация.</p></div></li><li><span>02</span><div><h3>Собираем сценарий</h3><p>Продумываем диалог, кнопки и передачу человеку. Согласуем нужные интеграции.</p></div></li><li><span>03</span><div><h3>Проверяем и запускаем</h3><p>Тестируем обычные и нестандартные ситуации. Показываю, как пользоваться результатом.</p></div></li></ol></section>'''
faq='''<section class="faq-section wrap"><p class="kicker">До начала работы</p><h2>Несколько честных ответов.</h2><details><summary>Нужен ли боту искусственный интеллект?</summary><p>Не всегда. Для записи и приёма заявок часто достаточно понятных кнопок и заранее продуманного сценария. ИИ имеет смысл подключать, когда есть задача, которую он действительно упрощает.</p></details><details><summary>Бот заменит менеджера?</summary><p>Он берёт на себя повторяющиеся действия. Сложные вопросы, договорённости и нестандартные случаи остаются у человека — переход к нему закладываем в сценарий.</p></details><details><summary>Можно подключить CRM или таблицу?</summary><p>Возможность интеграции зависит от выбранной системы, её API и доступов. Сначала проверяем ограничения, затем согласуем реализацию.</p></details><details><summary>Как узнать стоимость и сроки?</summary><p>Напишите, какую задачу хотите решить. После обсуждения сценария, платформы и интеграций смогу оценить объём, сроки и стоимость работы.</p></details></section>'''
contact='''<section class="contact-section wrap"><p class="kicker">Есть повторяющаяся задача?</p><h2>Расскажите,<br>что забирает время.</h2><div class="contact-bottom"><p>Достаточно описать процесс своими словами. Вместе поймём, где бот будет полезен.</p><a class="cta" href="https://telegram.me/Ilya_Manik">Написать Илье <span aria-hidden="true">↗</span></a></div></section>'''
def footer(slug):return f'''<footer class="wrap"><div class="footer-top"><a href="/">Илья Маник</a><span>Тестовая страница / 2026</span></div><div class="compare"><p>Сравнить оформление</p><nav aria-label="Другие варианты дизайна">{nav}</nav></div><p class="image-credit">Концептуальные иллюстрации созданы для этой страницы. Примеры диалогов демонстрационные.</p></footer>'''
def doc(slug,title,body):return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><title>{title} · Боты для бизнеса · Илья Маник</title><meta name="description" content="Боты для заявок, записи клиентов и ответов на частые вопросы. Три концепции оформления страницы Ильи Маника."><meta name="theme-color" content="{'#121312' if slug=='atmosphere' else '#f8f7f3'}"><link rel="icon" href="/assets/favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="/bots-lab/lab.css?v=1"><script defer src="/bots-lab/lab.js?v=1"></script></head><body class="{slug}">{body}</body></html>'''
editorial=header('01')+f'''<main id="main"><section class="editorial-hero wrap"><div class="hero-meta"><p class="kicker">Независимая цифровая практика</p><span>Концепция 01 / Редакционная</span></div><h1>Меньше рутины.<br><em>Больше дела.</em></h1><div class="hero-bottom"><p class="hero-lead">{lead}</p><a class="text-cta" href="#demo">Посмотреть на примере <span aria-hidden="true">↘</span></a></div><figure class="editorial-photo"><img src="/bots-lab/assets/order.webp" width="1536" height="1024" alt="Красный шнур соединяет стопку разрозненных карточек с аккуратно собранными заявками"><figcaption><span>Из потока сообщений — в понятный порядок.</span><span>Боты / сценарии / автоматизация</span></figcaption></figure></section>{tasks}{demo()}{process}{faq}{contact}</main>'''+footer('editorial')
product=header('02')+f'''<main id="main"><section class="product-hero wrap"><div class="product-hero-copy"><p class="kicker">Концепция 02 / Продуктовая</p><h1>Ваш следующий<br>помощник —<br><span>в переписке.</span></h1><p class="hero-lead">{lead}</p><a class="cta" href="#demo">Попробовать сценарий <span aria-hidden="true">↗</span></a><p class="hero-note">От понятного диалога — к действию.</p></div><div class="product-scene"><div class="scene-toolbar"><span class="scene-dot"></span><span>Путь одной заявки</span><span class="scene-date">пример</span></div><div class="scene-message"><span>Клиент</span><p>Здравствуйте! Можно записаться на консультацию?</p></div><div class="scene-connector" aria-hidden="true">↓</div><div class="scene-node"><span class="node-symbol" aria-hidden="true">м.</span><div><strong>Бот уточняет детали</strong><p>Услуга · удобное время · контакт</p></div></div><div class="scene-connector" aria-hidden="true">↓</div><div class="scene-ticket"><div><span class="ticket-label">Новая заявка</span><span class="ticket-status">Передана менеджеру</span></div><h3>Консультация</h3><dl><div><dt>Запрос</dt><dd>Обсудить задачу</dd></div><div><dt>Следующий шаг</dt><dd>Связаться с клиентом</dd></div></dl></div><p class="scene-caption">Иллюстрация сценария. Реальные заявки не создаются.</p></div></section><section class="product-band"><div class="wrap"><span>На входе — обычное сообщение.</span><strong>На выходе — понятное действие.</strong></div></section>{demo()}{tasks}<section class="product-photo wrap"><img loading="lazy" src="/bots-lab/assets/order.webp" width="1536" height="1024" alt="Порядок из разрозненных карточек: визуальная метафора автоматизации"><div><p class="kicker">Автоматизация без лишнего</p><h2>Удобно клиенту.<br>Понятно команде.</h2><p>Не перегружаем диалог. Собираем только нужные сведения и оставляем возможность поговорить с человеком.</p></div></section>{process}{faq}{contact}</main>'''+footer('product')
atmosphere=header('03')+f'''<main id="main"><section class="atmosphere-hero"><img class="atmosphere-photo" src="/bots-lab/assets/flow.webp" width="1536" height="864" alt="Красная нить проходит сквозь металлические арки: путь заявки через этапы работы"><div class="wrap atmosphere-content"><p class="kicker">Концепция 03 / Атмосферная</p><h1>Тихая работа.<br><span>Заметный<br>результат.</span></h1><div class="atmosphere-bottom"><p>{lead}</p><a class="round-link" href="#tasks" aria-label="Узнать, какие задачи решает бот">↓</a></div></div></section><section class="dark-statement wrap"><p class="kicker">Между сообщением и результатом</p><h2>Меньше переключений.<br>Больше внимания<br><em>к самому делу.</em></h2><p>Пока команда занимается людьми и решениями, бот помогает с повторяющимися шагами: уточнить, записать, передать, напомнить.</p></section>{tasks}{demo()}{process}{faq}{contact}</main>'''+footer('atmosphere')
for slug,_,name,_ in variants:
 p=R/slug;p.mkdir(exist_ok=True,parents=True);p.joinpath('index.html').write_text(doc(slug,name,locals()[slug]))
previews='''<div class="concept-grid" id="concepts">'''
for slug,n,name,desc in variants:
 visual={'editorial':'<span class="preview-type">Меньше рутины.<br><i>Больше дела.</i></span><img src="/bots-lab/assets/order.webp" alt="Редакционная концепция с фотоиллюстрацией" width="1536" height="1024">','product':'<div class="preview-product"><span>Клиент пишет</span><span>Бот уточняет</span><strong>Заявка у менеджера ↗</strong></div>','atmosphere':'<img src="/bots-lab/assets/flow.webp" alt="Тёмная концепция с красной нитью" width="1536" height="864"><span class="preview-dark-type">Тихая работа.<br>Заметный результат.</span>'}[slug]
 previews+=f'<a class="concept-card" href="/bots-lab/{slug}/"><div class="concept-preview preview-{slug}">{visual}</div><div class="concept-caption"><span>{n} / {name}</span><span aria-hidden="true">↗</span></div><p>{desc}</p></a>'
previews+='</div>'
hub=header('Выбор')+f'''<main id="main" class="hub-content wrap"><p class="kicker">Тестируем оформление</p><h1>Одна задача.<br>Три разных характера.</h1><p class="hub-lead">Выберите концепцию и откройте полноценную страницу про ботов. Сравниваем композицию, изображения и подачу — содержание и смысл остаются общими.</p>{previews}<p class="hub-note">Это дизайн-лаборатория. После выбора доработаем один вариант и перенесём его на основной сайт.</p></main>'''+footer('hub')
hub=hub.replace('href="#tasks">Задачи','href="#concepts">Варианты').replace('href="#demo">Пример','href="/bots-lab/product/#demo">Пример')
(R/'index.html').write_text(doc('hub','Три варианта дизайна',hub))
